// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _newMinSum) public {
        // Ensure _minSum and _newMinSum are distinct so we can detect change
        vm.assume(_minSum != _newMinSum);
        // Set an initial MinSum
        c.SetMinSum(_minSum);
        // Initialize the contract
        c.Initialized();
        // Record the MinSum after initialization
        uint256 minSumBefore = c.MinSum();
        // Try to call SetMinSum again (should revert in reference C)
        // Use try/catch to capture revert
        bool reverted;
        try c.SetMinSum(_newMinSum) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Assert that the call reverted (i.e., after initialization, SetMinSum cannot be called)
        assertTrue(reverted);
        // Also assert that MinSum did not change
        assertTrue(c.MinSum() == minSumBefore);
    }
}

